arguments.command:
cd /app/submit && python3 - << 'PY'
c=open('helper.c').read()
c=c.replace('''static inline int rat_less(int64_t an, int64_t ad, int64_t bn, int64_t bd)
{
    __int128 l = (__int128)an * (__int128)bd;
    __int128 r = (__int128)bn * (__int128)ad;
    return l < r;
}''','''/* Stage usages are bounded by ~4.2e6 bits (n <= 8192 nodes/rules/edges) and
 * capacities by 1e9, so both cross products always fit in int64.  __int128 is
 * used when the compiler offers it, purely as belt and braces. */
static inline int rat_less(int64_t an, int64_t ad, int64_t bn, int64_t bd)
{
#ifdef __SIZEOF_INT128__
    return (__int128)an * (__int128)bd < (__int128)bn * (__int128)ad;
#else
    return an * bd < bn * ad;
#endif
}''')
open('helper.c','w').write(c)
PY
grep -n "SIZEOF_INT128" helper.c; command -v clang tcc cc gcc; rm -f _scamp_helper.so; cd /app && python3 public_sanity.py
cd /app/submit && gcc -O2 -std=c11 -pedantic -Wall -Wextra -fPIC -shared -o /app/tmp/h_c11.so helper.c 2>&1 | head -20; echo "c11 pedantic rc=$?"
